/**
 * 기술 목록 — 사이트 전체에서 쓴 기술(조사: 2026-10-05, 코드 전체 grep + 주요 파일 확인)과
 * 아직 안 썼지만 쓸 수 있는 기술(idea). 스튜디오 「기술 목록」 칸이 이 표를 보여 준다.
 * 새 기술을 쓰면 status 를 'used' 로 바꾸고 where · files 를 채운다. demo 는 스튜디오 칸 id (있으면 바로 가기).
 */

import { curate } from './curation';

export type Dim = '2D' | '3D' | '공통';
export interface Tech {
  /** 고유 번호 — u = 쓰는 중, i = 아이디어 (견본 demos/*.ts 의 열쇠) */
  id: string;
  cat: string;
  name: string;
  dim: Dim;
  status: 'used' | 'idea';
  desc: string;
  /** used: 쓰는 게임 · idea: 쓰면 좋을 곳 */
  where: string;
  files?: string;
  demo?: string;
  /** 난이도 (아이디어) — 하: 하루 · 중: 며칠 · 상: 셰이더 · GPU 계산 깊게 */
  lv?: '하' | '중' | '상';
  /** 참고 주소 (조사에서 실제로 확인한 것만) */
  ref?: string;
  /** 효과 모음 — 이 기술의 상위 기술 id (목록에는 안 나오고 상위 기술 화면에 모여 보임, curation.ts) */
  of?: string;
}

const U = (id: string, cat: string, dim: Dim, name: string, desc: string, where: string, files = '', demo = ''): Tech => ({ id, cat, name, dim, status: 'used', desc, where, files, demo });
const I = (id: string, cat: string, dim: Dim, name: string, desc: string, where: string, lv?: '하' | '중' | '상', ref?: string): Tech => ({ id, cat, name, dim, status: 'idea', desc, where, lv, ref });

