/** 공개 목록 (curation.ts 로 빼기 · 옮기기 · 이름 고치기를 건 것) — 효과 모음(of) 포함 */
export const TECH: Tech[] = curate(ALL_TECH);
/** 목록 · 숫자에 나오는 기술 (효과 모음 빼고) */
export const MAIN: Tech[] = TECH.filter((t) => !t.of);
/** 상위 기술의 효과 모음 */
export const variantsOf = (id: string): Tech[] => TECH.filter((t) => t.of === id);

